import { describe, expect, test } from 'bun:test';
import {
  filterAndSortCommands,
  type CommandAutocompleteSearchItem,
} from '../commandAutocompleteItems';

// Expected orders come from Pi's own slash autocomplete
// (@earendil-works/pi-tui 1.1.0, CombinedAutocompleteProvider.getSuggestions):
// fuzzyFilter over the bare name of a skill:, then skill: commands that only
// match their full name. Generated by running pi-tui's fuzzyFilter on this catalog.
const catalog: CommandAutocompleteSearchItem[] = [
  { name: 'compact', source: 'pichamber', isBuiltIn: true, description: 'Compact the context' },
  { name: 'prompt-workflow', source: 'prompt', description: 'Prompt workflow' },
  { name: 'sandy-context', source: 'extension', description: 'Context tools' },
  { name: 'proto-thing', source: 'extension', description: 'Proto thing' },
  { name: 'review', source: 'prompt', description: 'Review changes' },
  { name: 'skill:audit-tests', invocationName: 'skill:audit-tests', source: 'skill', isSkill: true, description: 'Audit tests' },
  { name: 'skill:auto-research', invocationName: 'skill:auto-research', source: 'skill', isSkill: true, description: 'Research' },
  {
    name: 'skill:principle-exhaust-the-design-space',
    invocationName: 'skill:principle-exhaust-the-design-space',
    source: 'skill',
    isSkill: true,
    description: 'Weigh designs for a novel decision',
  },
  { name: 'skill:principle-prove-it-works', invocationName: 'skill:principle-prove-it-works', source: 'skill', isSkill: true, description: 'Prove it' },
  { name: 'skill:prototype', invocationName: 'skill:prototype', source: 'skill', isSkill: true, description: 'Build a disposable experiment' },
  { name: 'skill:review', invocationName: 'skill:review', source: 'skill', isSkill: true, description: 'Close out a slice' },
  { name: 'skill:write-tests', invocationName: 'skill:write-tests', source: 'skill', isSkill: true, description: 'Write tests' },
];

const names = (query: string, category: Parameters<typeof filterAndSortCommands>[2] = 'all') =>
  filterAndSortCommands(catalog, query, category).map((item) => item.invocationName ?? item.name);

describe('filterAndSortCommands: name matches follow Pi slash autocomplete (#184)', () => {
  test('/prototype lists only skill:prototype, not skill:principle-exhaust-the-design-space', () => {
    expect(names('prototype')).toEqual(['skill:prototype']);
  });

  test('/protot puts skill:prototype first, not prompts that only match loosely', () => {
    expect(names('protot')).toEqual(['skill:prototype', 'proto-thing']);
  });

  test('a prefix of the skill: name works as in Pi', () => {
    expect(names('skill:proto').slice(0, 2)).toEqual(['skill:prototype', 'skill:principle-prove-it-works']);
  });

  test('a bare name ranks a skill with that name right behind the plain command', () => {
    expect(names('rev').slice(0, 3)).toEqual(['review', 'skill:review', 'skill:principle-prove-it-works']);
    expect(names('tests').slice(0, 2)).toEqual(['skill:audit-tests', 'skill:write-tests']);
  });

  test('categories still filter before ranking', () => {
    expect(names('protot', 'skills')).toEqual(['skill:prototype']);
    expect(names('protot', 'extensions')).toEqual(['proto-thing']);
    expect(names('protot', 'prompts')).toEqual([]);
    expect(names('', 'system')).toEqual(['compact']);
  });

  test('equal name scores keep catalog order, as in Pi\'s stable sort', () => {
    expect(names('proto')).toEqual([
      'proto-thing',
      'skill:prototype',
      'prompt-workflow',
      'skill:principle-prove-it-works',
    ]);
  });
});

describe('filterAndSortCommands: description and alias matches come last (#184)', () => {
  const withMeta: CommandAutocompleteSearchItem[] = [
    { name: 'deploy-docs', source: 'prompt', description: 'Publish the handbook' },
    { name: 'handbook-sync', source: 'prompt', description: 'Sync' },
    { name: 'ship-it', source: 'prompt', description: 'Release/publish now', searchAliases: ['team-handbook'] },
    { name: 'publish-all', source: 'prompt', description: 'Everything' },
    { name: 'unrelated', source: 'prompt', description: 'Nothing here' },
  ];
  const run = (query: string, category: Parameters<typeof filterAndSortCommands>[2] = 'all') =>
    filterAndSortCommands(withMeta, query, category).map((item) => item.name);

  test('a command reachable only by a word start in its description or alias follows every name match', () => {
    // handbook-sync by name; deploy-docs by description; ship-it by the alias word after "-".
    expect(run('handbook')).toEqual(['handbook-sync', 'deploy-docs', 'ship-it']);
    // "publish" after a "/" in a description is a word start too.
    expect(run('publish')).toEqual(['publish-all', 'deploy-docs', 'ship-it']);
    // a prefix of a word counts, case-insensitively
    expect(run('HAND')).toEqual(['handbook-sync', 'deploy-docs', 'ship-it']);
  });

  test('scattered letters and mid word text do not match a description (no flooding)', () => {
    const catalogWithSim: CommandAutocompleteSearchItem[] = [
      { name: 'prototype', invocationName: 'skill:prototype', source: 'skill', isSkill: true, description: 'Build a disposable experiment' },
      {
        name: 'serve-sim',
        invocationName: 'skill:serve-sim',
        source: 'skill',
        isSkill: true,
        description: 'Boot, install and launch the Capacitor iOS app, stream it, tap, type, rotate and inspect accessibility',
      },
    ];
    const find = (query: string) => filterAndSortCommands(catalogWithSim, query, 'all').map((item) => item.invocationName);
    expect(find('prototype')).toEqual(['skill:prototype']);
    expect(find('accessibility')).toEqual(['skill:serve-sim']);
    expect(find('cessibility')).toEqual([]);
    expect(find('capacitor ios')).toEqual(['skill:serve-sim']);
  });

  test('a command is listed once, in catalog order within the group', () => {
    expect(run('handbook').filter((name) => name === 'ship-it')).toHaveLength(1);
    expect(run('hand').indexOf('deploy-docs')).toBeLessThan(run('hand').indexOf('ship-it'));
  });

  test('the name part stays exactly Pi: it does not change when metadata is added', () => {
    const nameOnly = catalog.map((item) => ({ ...item, description: undefined, searchAliases: undefined }));
    for (const query of ['proto', 'protot', 'prototype', 'skill:proto', 'rev', 'tests']) {
      const expected = filterAndSortCommands(nameOnly, query, 'all').map((item) => item.name);
      const actual = filterAndSortCommands(catalog, query, 'all').map((item) => item.name);
      expect(actual.slice(0, expected.length)).toEqual(expected);
    }
  });

  test('categories filter the metadata group too, and an empty query is unchanged', () => {
    expect(run('handbook', 'skills')).toEqual([]);
    expect(run('')).toEqual(withMeta.map((item) => item.name));
  });
});
